def is_valid_number(s: str, allow_decimal: bool = False) -> bool:
    """
    Validate a number string.
    - Must contain only ASCII digits and optionally '.' or ','
    - If allow_decimal is False, decimals are not allowed
    - If allow_decimal is True, decimals are only allowed as the last component
    - Decimal point must have digits on both sides
    """
    if not s:
        return False

    # Check for valid characters (digits, '.', ',')
    for char in s:
        if not (char.isdigit() and ord(char) < 128) and char not in '.,:
            return False

    # Can't have both '.' and ','
    if '.' in s and ',' in s:
        return False

    decimal_char = '.' if '.' in s else (',' if ',' in s else None)

    if decimal_char:
        if not allow_decimal:
            return False
        parts = s.split(decimal_char)
        # Must have exactly 2 parts with both non-empty
        if len(parts) != 2 or not parts[0] or not parts[1]:
            return False
        # Both parts must be digits
        if not parts[0].isdigit() or not parts[1].isdigit():
            return False
    else:
        # No decimal, must be all digits
        if not s.isdigit():
            return False

    return True

